  virtual ccxt::any parseTradingFees(ccxt::any response) {
    ccxt::any result = ccxt::dict{};
    ccxt::any symbols = this->symbols;
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(symbols));
         postFixIncrement(i)) {
      ccxt::any symbol = ::getValue(symbols, i);
      ccxt::any market = this->market(symbol);
      ::setValue(result, symbol, this->parseTradingFee(response, market));
    }
    return result;
  }

  virtual ccxt::any parseTradingFee(ccxt::any info,
                                    ccxt::any market = ccxt::any{}) {
    //
    //    {
    //        "user_id": 1486602,
    //        "taker_fee": "0.002",
    //        "maker_fee": "0.002",
    //        "gt_discount": true,
    //        "gt_taker_fee": "0.0015",
    //        "gt_maker_fee": "0.0015",
    //        "loan_fee": "0.18",
    //        "point_type": "0",
    //        "futures_taker_fee": "0.0005",
    //        "futures_maker_fee": "0"
    //    }
    //
    ccxt::any gtDiscount = this->safeValue(info, std::string("gt_discount"));
    ccxt::any taker = (isTrue((isEqual(gtDiscount, true)))
                           ? ccxt::any(std::string("gt_taker_fee"))
                           : ccxt::any(std::string("taker_fee")));
    ccxt::any maker = (isTrue((isEqual(gtDiscount, true)))
                           ? ccxt::any(std::string("gt_maker_fee"))
                           : ccxt::any(std::string("maker_fee")));
    ccxt::any contract = this->safeValue(market, std::string("contract"));
    ccxt::any takerKey = (isTrue((isEqual(contract, true)))
                              ? ccxt::any(std::string("futures_taker_fee"))
                              : ccxt::any(taker));
    ccxt::any makerKey = (isTrue((isEqual(contract, true)))
                              ? ccxt::any(std::string("futures_maker_fee"))
                              : ccxt::any(maker));
    return ccxt::dict{
        {std::string("info"), info},
        {std::string("symbol"),
         this->safeString(market, std::string("symbol"))},
        {std::string("maker"), this->safeNumber(info, makerKey)},
        {std::string("taker"), this->safeNumber(info, takerKey)},
        {std::string("percentage"), ccxt::any{}},
        {std::string("tierBased"), ccxt::any{}},
    };
  }

  /**
   * @method
   * @name gate#fetchTransactionFees
   * @deprecated
   * @description please use fetchDepositWithdrawFees instead
   * @see https://www.gate.com/docs/developers/apiv4/en/#query-withdrawal-status
   * @param {string[]|undefined} codes list of unified currency codes
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a list of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<ccxt::any>
  fetchTransactionFees(ccxt::any codes = ccxt::any{},
                       ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any response =
                     awaitValue(this->privateWalletGetWithdrawStatus(params));
                 //
                 //    {
                 //        "currency": "MTN",
                 //        "name": "Medicalchain",
                 //        "name_cn": "Medicalchain",
                 //        "deposit": "0",
                 //        "withdraw_percent": "0%",
                 //        "withdraw_fix": "900",
                 //        "withdraw_day_limit": "500000",
                 //        "withdraw_day_limit_remain": "500000",
                 //        "withdraw_amount_mini": "900.1",
                 //        "withdraw_eachtime_limit": "90000000000",
                 //        "withdraw_fix_on_chains": {
                 //            "ETH": "900"
                 //        }
                 //    }
                 //
                 ccxt::any result = ccxt::dict{};
                 ccxt::any withdrawFees = ccxt::dict{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(response));
                      postFixIncrement(i)) {
                   withdrawFees = ccxt::dict{};
                   ccxt::any entry = this->safeDict(response, i, ccxt::dict{});
                   ccxt::any currencyId =
                       this->safeString(entry, std::string("currency"));
                   ccxt::any code = this->safeCurrencyCode(currencyId);
                   if (isTrue(isTrue((!isEqual(codes, ccxt::any{}))) &&
                              !isTrue(this->inArray(code, codes)))) {
                     continue;
                   }
                   ccxt::any withdrawFixOnChains = this->safeValue(
                       entry, std::string("withdraw_fix_on_chains"));
                   if (isTrue(isEqual(withdrawFixOnChains, ccxt::any{}))) {
                     withdrawFees =
                         this->safeNumber(entry, std::string("withdraw_fix"));
                   } else {
                     ccxt::any networkIds = getObjectKeys(withdrawFixOnChains);
                     for (ccxt::any j = 0;
                          isLessThan(j, getArrayLength(networkIds));
                          postFixIncrement(j)) {
                       ccxt::any networkId = ::getValue(networkIds, j);
                       ccxt::any networkCode =
                           this->networkIdToCode(networkId, code);
                       if (isTrue(!isEqual(networkCode, ccxt::any{}))) {
                         ::setValue(withdrawFees, networkCode,
                                    this->parseNumber(::getValue(
                                        withdrawFixOnChains, networkId)));
                       }
                     }
                   }
                   ::setValue(result, code,
                              ccxt::dict{
                                  {std::string("withdraw"), withdrawFees},
                                  {std::string("deposit"), ccxt::any{}},
                                  {std::string("info"), entry},
                              });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name gate#fetchDepositWithdrawFees
   * @description fetch deposit and withdraw fees
   * @see https://www.gate.com/docs/developers/apiv4/en/#query-withdrawal-status
   * @param {string[]|undefined} codes list of unified currency codes
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a list of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<ccxt::any>
  fetchDepositWithdrawFees(ccxt::any codes = ccxt::any{},
                           ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any response = awaitValue(
                            this->privateWalletGetWithdrawStatus(params));
                        //
                        //    [
                        //        {
                        //            "currency": "MTN",
                        //            "name": "Medicalchain",
                        //            "name_cn": "Medicalchain",
                        //            "deposit": "0",
                        //            "withdraw_percent": "0%",
                        //            "withdraw_fix": "900",
                        //            "withdraw_day_limit": "500000",
                        //            "withdraw_day_limit_remain": "500000",
                        //            "withdraw_amount_mini": "900.1",
                        //            "withdraw_eachtime_limit": "90000000000",
                        //            "withdraw_fix_on_chains": {
                        //                "ETH": "900"
                        //            }
                        //        }
                        //    ]
                        //
                        return this->parseDepositWithdrawFees(
                            response, codes, std::string("currency"));
                      })
        .share();
  }

  ccxt::any parseDepositWithdrawFee(ccxt::any fee,
                                    ccxt::any currency = ccxt::any{}) override {
    //
    //    {
    //        "currency": "MTN",
    //        "name": "Medicalchain",
    //        "name_cn": "Medicalchain",
    //        "deposit": "0",
    //        "withdraw_percent": "0%",
    //        "withdraw_fix": "900",
    //        "withdraw_day_limit": "500000",
    //        "withdraw_day_limit_remain": "500000",
    //        "withdraw_amount_mini": "900.1",
    //        "withdraw_eachtime_limit": "90000000000",
    //        "withdraw_fix_on_chains": {
    //            "ETH": "900"
    //        }
    //    }
    //
    ccxt::any withdrawFixOnChains =
        this->safeValue(fee, std::string("withdraw_fix_on_chains"));
    ccxt::any result = ccxt::dict{
        {std::string("info"), fee},
        {std::string("withdraw"),
         ccxt::dict{
             {std::string("fee"),
              this->safeNumber(fee, std::string("withdraw_fix"))},
             {std::string("percentage"), false},
         }},
        {std::string("deposit"),
         ccxt::dict{
             {std::string("fee"),
              this->safeNumber(fee, std::string("deposit"))},
             {std::string("percentage"), false},
         }},
        {std::string("networks"), ccxt::dict{}},
    };
    if (isTrue(!isEqual(withdrawFixOnChains, ccxt::any{}))) {
      ccxt::any chainKeys = getObjectKeys(withdrawFixOnChains);
      for (ccxt::any i = 0; isLessThan(i, getArrayLength(chainKeys));
           postFixIncrement(i)) {
        ccxt::any chainKey = ::getValue(chainKeys, i);
        ccxt::any currencyId = this->safeString(fee, std::string("currency"));
        ccxt::any code = this->safeCurrencyCode(currencyId, currency);
        ccxt::any networkCode = this->networkIdToCode(chainKey, code);
        if (isTrue(!isEqual(networkCode, ccxt::any{}))) {
          ::setValue(::getValue(result, std::string("networks")), networkCode,
                     ccxt::dict{
                         {std::string("withdraw"),
                          ccxt::dict{
                              {std::string("fee"),
                               this->parseNumber(
                                   ::getValue(withdrawFixOnChains, chainKey))},
                              {std::string("percentage"), false},
                          }},
                         {std::string("deposit"),
                          ccxt::dict{
                              {std::string("fee"), ccxt::any{}},
                              {std::string("percentage"), ccxt::any{}},
                          }},
                     });
        }
      }
    }
    return result;
  }

  /**
   * @method
   * @name gate#fetchFundingHistory
   * @description fetch the history of funding payments paid and received on
   * this account
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-futures-account-change-history
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-futures-account-change-history-2
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch funding history for
   * @param {int} [limit] the maximum number of funding history structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [funding history structure]{@link
   * https://docs.ccxt.com/?id=funding-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 // let defaultType = 'future';
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   symbol = ::getValue(market, std::string("symbol"));
                 }
                 ccxt::any typequeryVariable = this->handleMarketTypeAndParams(
                     std::string("fetchFundingHistory"), market, params);
                 ccxt::any type = ::getValue(typequeryVariable, 0);
                 ccxt::any query = ::getValue(typequeryVariable, 1);
                 ccxt::any requestrequestParamsVariable =
                     this->prepareRequest(market, type, query);
                 ccxt::any request =
                     ::getValue(requestrequestParamsVariable, 0);
                 ccxt::any requestParams =
                     ::getValue(requestrequestParamsVariable, 1);
                 ::setValue(
                     request, std::string("type"),
                     std::string(
                         "fund")); // 'dnw' 'pnl' 'fee' 'refr' 'fund'
                                   // 'point_dnw' 'point_fee' 'point_refr'
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   // from should be integer
                   ::setValue(request, std::string("from"),
                              this->parseToInt(divide(since, 1000)));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(type, std::string("swap")))) {
                   response =
                       awaitValue(this->privateFuturesGetSettleAccountBook(
                           this->extend(request, requestParams)));
                 } else if (isTrue(isEqual(type, std::string("future")))) {
                   response =
                       awaitValue(this->privateDeliveryGetSettleAccountBook(
                           this->extend(request, requestParams)));
                 } else {
                   throw NotSupported(toString(
                       add(this->id,
                           std::string(" fetchFundingHistory() only support "
                                       "swap & future market type"))));
                 }
                 //
                 //    [
                 //        {
                 //            "time": 1646899200,
                 //            "change": "-0.027722",
                 //            "balance": "11.653120591841",
                 //            "text": "XRP_USDT",
                 //            "type": "fund"
                 //        },
                 //        ...
                 //    ]
                 //
                 return this->parseFundingHistories(response, symbol, since,
                                                    limit);
               })
        .share();
  }

  virtual ccxt::any parseFundingHistories(ccxt::any response, ccxt::any symbol,
                                          ccxt::any since, ccxt::any limit) {
    ccxt::any result = ccxt::list{};
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(response));
         postFixIncrement(i)) {
      ccxt::any entry = ::getValue(response, i);
      ccxt::any funding = this->parseFundingHistory(entry);
      arrayPush(result, funding);
    }
    ccxt::any sorted = this->sortBy(result, std::string("timestamp"));
    return this->filterBySymbolSinceLimit(sorted, symbol, since, limit);
  }

  virtual ccxt::any parseFundingHistory(ccxt::any info,
                                        ccxt::any market = ccxt::any{}) {
    //
    //    {
    //        "time": 1646899200,
    //        "change": "-0.027722",
    //        "balance": "11.653120591841",
    //        "text": "XRP_USDT",
    //        "type": "fund"
    //    }
    //
    ccxt::any timestamp = this->safeTimestamp(info, std::string("time"));
    ccxt::any marketId = this->safeString(info, std::string("text"));
    market = this->safeMarket(marketId, market, std::string("_"),
                              std::string("swap"));
    return ccxt::dict{
        {std::string("info"), info},
        {std::string("symbol"),
         this->safeString(market, std::string("symbol"))},
        {std::string("code"), this->safeString(market, std::string("settle"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("id"), ccxt::any{}},
        {std::string("amount"), this->safeNumber(info, std::string("change"))},
    };
  }

  /**
   * @method
   * @name gate#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-market-depth-information
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-futures-market-depth-information
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-futures-market-depth-information-2
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-options-contract-order-book
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 //
                 //     const request: Dict = {
                 //         'currency_pair': market['id'],
                 //         'interval': '0', // depth, 0 means no aggregation is
                 //         applied, default to 0 'limit': limit, // maximum
                 //         number of order depth data in asks or bids
                 //         'with_id': true, // return order book ID
                 //     };
                 //
                 ccxt::any requestqueryVariable = this->prepareRequest(
                     market, ::getValue(market, std::string("type")), params);
                 ccxt::any request = ::getValue(requestqueryVariable, 0);
                 ccxt::any query = ::getValue(requestqueryVariable, 1);
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                      true))) {
                     limit = mathMin(limit, 1000);
                   } else {
                     limit = mathMin(limit, 300);
                   }
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ::setValue(request, std::string("with_id"), true);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(
                         isTrue((isEqual(
                             ::getValue(market, std::string("spot")), true))) ||
                         isTrue(
                             (isEqual(::getValue(market, std::string("margin")),
                                      true))))) {
                   response = awaitValue(this->publicSpotGetOrderBook(
                       this->extend(request, query)));
                 } else if (isTrue(
                                isEqual(::getValue(market, std::string("swap")),
                                        true))) {
                   response = awaitValue(this->publicFuturesGetSettleOrderBook(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(
                                ::getValue(market, std::string("future")),
                                true))) {
                   response = awaitValue(this->publicDeliveryGetSettleOrderBook(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(
                                ::getValue(market, std::string("option")),
                                true))) {
                   response = awaitValue(this->publicOptionsGetOrderBook(
                       this->extend(request, query)));
                 } else {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(
                           " fetchOrderBook() not support this market type"))));
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "id": 6358770031
                 //         "current": 1634345973275,
                 //         "update": 1634345973271,
                 //         "asks": [
                 //             ["2.2241","12449.827"],
                 //             ["2.2242","200"],
                 //             ["2.2244","826.931"],
                 //             ["2.2248","3876.107"],
                 //             ["2.225","2377.252"],
                 //             ["2.22509","439.484"],
                 //             ["2.2251","1489.313"],
                 //             ["2.2253","714.582"],
                 //             ["2.2254","1349.784"],
                 //             ["2.2256","234.701"]],
                 //          "bids": [
                 //             ["2.2236","32.465"],
                 //             ["2.2232","243.983"],
                 //             ["2.2231","32.207"],
                 //             ["2.223","449.827"],
                 //             ["2.2228","7.918"],
                 //             ["2.2227","12703.482"],
                 //             ["2.2226","143.033"],
                 //             ["2.2225","143.027"],
                 //             ["2.2224","1369.352"],
                 //             ["2.2223","756.063"]
                 //         ]
                 //     }
                 //
                 // swap, future and option
                 //
                 //     {
                 //         "id": 6358770031
                 //         "current": 1634350208.745,
                 //         "asks": [
                 //             {"s": 24909, "p": "61264.8"},
                 //             {"s": 81, "p": "61266.6"},
                 //             {"s": 2000, "p": "61267.6"},
                 //             {"s": 490, "p": "61270.2"},
                 //             {"s": 12, "p": "61270.4"},
                 //             {"s": 11782, "p": "61273.2"},
                 //             {"s": 14666, "p": "61273.3"},
                 //             {"s": 22541, "p": "61273.4"},
                 //             {"s": 33, "p": "61273.6"},
                 //             {"s": 11980, "p": "61274.5"}
                 //         ],
                 //         "bids": [
                 //             {"s": 41844, "p": "61264.7"},
                 //             {"s": 13783, "p": "61263.3"},
                 //             {"s": 1143, "p": "61259.8"},
                 //             {"s": 81, "p": "61258.7"},
                 //             {"s": 2471, "p": "61257.8"},
                 //             {"s": 2471, "p": "61257.7"},
                 //             {"s": 2471, "p": "61256.5"},
                 //             {"s": 3, "p": "61254.2"},
                 //             {"s": 114, "p": "61252.4"},
                 //             {"s": 14372, "p": "61248.6"}
                 //         ],
                 //         "update": 1634350208.724
                 //     }
                 //
                 ccxt::any timestamp =
                     this->safeInteger(response, std::string("current"));
                 if (isTrue(isEqual(timestamp, ccxt::any{}))) {
                   throw ExchangeError(toString(add(
                       this->id, std::string(" method() missing timestamp"))));
                 }
                 if (isTrue(!isEqual(::getValue(market, std::string("spot")),
                                     true))) {
                   timestamp = multiply(timestamp, 1000);
                 }
                 ccxt::any priceKey =
                     (isTrue((isEqual(::getValue(market, std::string("spot")),
                                      true)))
                          ? ccxt::any(0)
                          : ccxt::any(std::string("p")));
                 ccxt::any amountKey =
                     (isTrue((isEqual(::getValue(market, std::string("spot")),
                                      true)))
                          ? ccxt::any(1)
                          : ccxt::any(std::string("s")));
                 ccxt::any nonce =
                     this->safeInteger(response, std::string("id"));
                 ccxt::any result = this->parseOrderBook(
                     response, symbol, timestamp, std::string("bids"),
                     std::string("asks"), priceKey, amountKey);
                 ::setValue(result, std::string("nonce"), nonce);
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name gate#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-currency-pair-ticker-information
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-all-futures-trading-statistics
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-all-futures-trading-statistics-2
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-options-market-ticker-information
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any requestqueryVariable =
                     this->prepareRequest(market, ccxt::any{}, params);
                 ccxt::any request = ::getValue(requestqueryVariable, 0);
                 ccxt::any query = ::getValue(requestqueryVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(
                         isTrue((isEqual(
                             ::getValue(market, std::string("spot")), true))) ||
                         isTrue(
                             (isEqual(::getValue(market, std::string("margin")),
                                      true))))) {
                   response = awaitValue(this->publicSpotGetTickers(
                       this->extend(request, query)));
                 } else if (isTrue(
                                isEqual(::getValue(market, std::string("swap")),
                                        true))) {
                   response = awaitValue(this->publicFuturesGetSettleTickers(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(
                                ::getValue(market, std::string("future")),
                                true))) {
                   response = awaitValue(this->publicDeliveryGetSettleTickers(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(
                                ::getValue(market, std::string("option")),
                                true))) {
                   ccxt::any marketId = ::getValue(market, std::string("id"));
                   ccxt::any optionParts = split(marketId, std::string("-"));
                   ::setValue(request, std::string("underlying"),
                              this->safeString(optionParts, 0));
                   response = awaitValue(this->publicOptionsGetTickers(
                       this->extend(request, query)));
                 } else {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(
                           " fetchTicker() not support this market type"))));
                 }
                 ccxt::any ticker = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("option")),
                                    true))) {
                   for (ccxt::any i = 0;
                        isLessThan(i, getArrayLength(response));
                        postFixIncrement(i)) {
                     ccxt::any entry = ::getValue(response, i);
                     if (isTrue(
                             isEqual(::getValue(entry, std::string("name")),
                                     ::getValue(market, std::string("id"))))) {
                       ticker = entry;
                       break;
                     }
                   }
                 } else {
                   ticker = this->safeValue(response, 0);
                 }
                 if (isTrue(isEqual(ticker, ccxt::any{}))) {
                   throw NullResponse(toString(add(
                       this->id,
                       std::string(" fetchTicker() returned empty response"))));
                 }
                 return this->parseTicker(ticker, market);
               })
        .share();
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    // SPOT
    //
    //     {
    //         "currency_pair": "KFC_USDT",
    //         "last": "7.255",
    //         "lowest_ask": "7.298",
    //         "highest_bid": "7.218",
    //         "change_percentage": "-1.18",
    //         "base_volume": "1219.053687865",
    //         "quote_volume": "8807.40299875455",
    //         "high_24h": "7.262",
    //         "low_24h": "7.095"
    //     }
    //
    // LINEAR/DELIVERY
    //
    //     {
    //         "contract": "BTC_USDT",
    //         "last": "6432",
    //         "low_24h": "6278",
    //         "high_24h": "6790",
    //         "change_percentage": "4.43",
    //         "total_size": "32323904",
    //         "volume_24h": "184040233284",
    //         "volume_24h_btc": "28613220",
    //         "volume_24h_usd": "184040233284",
    //         "volume_24h_base": "28613220",
    //         "volume_24h_quote": "184040233284",
    //         "volume_24h_settle": "28613220",
    //         "mark_price": "6534",
    //         "funding_rate": "0.0001",
    //         "funding_rate_indicative": "0.0001",
    //         "index_price": "6531"
    //     }
    //
    // bookTicker
    //    {
    //        "t": 1671363004228,
    //        "u": 9793320464,
    //        "s": "BTC_USDT",
    //        "b": "16716.8", // best bid price
    //        "B": "0.0134", // best bid size
    //        "a": "16716.9", // best ask price
    //        "A": "0.0353" // best ask size
    //     }
    //
    // option
    //
    //     {
    //         "vega": "0.00002",
    //         "leverage": "12.277188268663",
    //         "ask_iv": "0",
    //         "delta": "-0.99999",
    //         "last_price": "0",
    //         "theta": "-0.00661",
    //         "bid1_price": "1096",
    //         "mark_iv": "0.7799",
    //         "name": "BTC_USDT-20230608-28500-P",
    //         "bid_iv": "0",
    //         "ask1_price": "2935",
    //         "mark_price": "2147.3",
    //         "position_size": 0,
    //         "bid1_size": 12,
    //         "ask1_size": -14,
    //         "gamma": "0"
    //     }
    //
    ccxt::any marketId = this->safeStringN(
        ticker, ccxt::list{std::string("currency_pair"),
                           std::string("contract"), std::string("name")});
    ccxt::any marketType = (isTrue((inOp(ticker, std::string("mark_price"))))
                                ? ccxt::any(std::string("contract"))
                                : ccxt::any(std::string("spot")));
    ccxt::any symbol =
        this->safeSymbol(marketId, market, std::string("_"), marketType);
    ccxt::any last = this->safeString2(ticker, std::string("last"),
                                       std::string("last_price"));
    ccxt::any ask = this->safeStringN(
        ticker, ccxt::list{std::string("lowest_ask"), std::string("a"),
                           std::string("ask1_price")});
    ccxt::any bid = this->safeStringN(
        ticker, ccxt::list{std::string("highest_bid"), std::string("b"),
                           std::string("bid1_price")});
    ccxt::any high = this->safeString(ticker, std::string("high_24h"));
    ccxt::any low = this->safeString(ticker, std::string("low_24h"));
    ccxt::any bidVolume =
        this->safeString2(ticker, std::string("B"), std::string("bid1_size"));
    ccxt::any askVolume =
        this->safeString2(ticker, std::string("A"), std::string("ask1_size"));
    ccxt::any timestamp = this->safeInteger(ticker, std::string("t"));
    ccxt::any baseVolume = this->safeString2(ticker, std::string("base_volume"),
                                             std::string("volume_24h_base"));
    if (isTrue(isEqual(baseVolume, std::string("nan")))) {
      baseVolume = std::string("0");
    }
    ccxt::any quoteVolume = this->safeString2(
        ticker, std::string("quote_volume"), std::string("volume_24h_quote"));
    if (isTrue(isEqual(quoteVolume, std::string("nan")))) {
      quoteVolume = std::string("0");
    }
    ccxt::any percentage =
        this->safeString(ticker, std::string("change_percentage"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"), high},
            {std::string("low"), low},
            {std::string("bid"), bid},
            {std::string("bidVolume"), bidVolume},
            {std::string("ask"), ask},
            {std::string("askVolume"), askVolume},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"), ccxt::any{}},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), ccxt::any{}},
            {std::string("change"), ccxt::any{}},
            {std::string("percentage"), percentage},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"), baseVolume},
            {std::string("quoteVolume"), quoteVolume},
            {std::string("markPrice"),
             this->safeString(ticker, std::string("mark_price"))},
            {std::string("indexPrice"),
             this->safeString(ticker, std::string("index_price"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name gate#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-currency-pair-ticker-information
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-all-futures-trading-statistics
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-all-futures-trading-statistics-2
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-options-market-ticker-information
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols);
                 ccxt::any first = this->safeString(symbols, 0);
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(first, ccxt::any{}))) {
                   market = this->market(first);
                 }
                 ccxt::any typequeryVariable = this->handleMarketTypeAndParams(
                     std::string("fetchTickers"), market, params);
                 ccxt::any type = ::getValue(typequeryVariable, 0);
                 ccxt::any query = ::getValue(typequeryVariable, 1);
                 ccxt::any requestrequestParamsVariable =
                     this->prepareRequest(ccxt::any{}, type, query);
                 ccxt::any request =
                     ::getValue(requestrequestParamsVariable, 0);
                 ccxt::any requestParams =
                     ::getValue(requestrequestParamsVariable, 1);
                 ccxt::any response = ccxt::any{};
                 ::setValue(request, std::string("timezone"),
                            std::string("utc0")); // default to utc
                 if (isTrue(isTrue(isEqual(type, std::string("spot"))) ||
                            isTrue(isEqual(type, std::string("margin"))))) {
                   response = awaitValue(this->publicSpotGetTickers(
                       this->extend(request, requestParams)));
                 } else if (isTrue(isEqual(type, std::string("swap")))) {
                   response = awaitValue(this->publicFuturesGetSettleTickers(
                       this->extend(request, requestParams)));
                 } else if (isTrue(isEqual(type, std::string("future")))) {
                   response = awaitValue(this->publicDeliveryGetSettleTickers(
                       this->extend(request, requestParams)));
                 } else if (isTrue(isEqual(type, std::string("option")))) {
                   this->checkRequiredArgument(std::string("fetchTickers"),
                                               symbols, std::string("symbols"));
                   ccxt::any marketId =
                       this->safeString(market, std::string("id"));
                   ccxt::any optionParts = split(marketId, std::string("-"));
                   ::setValue(request, std::string("underlying"),
                              this->safeString(optionParts, 0));
                   response = awaitValue(this->publicOptionsGetTickers(
                       this->extend(request, requestParams)));
                 } else {
                   throw NotSupported(toString(
                       add(this->id,
                           std::string(
                               " fetchTickers() not support this market type, "
                               "provide symbols or set params[\"defaultType\"] "
                               "to one from spot/margin/swap/future/option"))));
                 }
                 return this->parseTickers(response, symbols);
               })
        .share();
  }

  virtual ccxt::any parseBalanceHelper(ccxt::any entry) {
    ccxt::any account = this->account();
    ::setValue(
        account, std::string("used"),
        this->safeString2(entry, std::string("freeze"), std::string("locked")));
    ::setValue(account, std::string("free"),
               this->safeString(entry, std::string("available")));
    ::setValue(account, std::string("total"),
               this->safeString(entry, std::string("total")));
    if (isTrue(inOp(entry, std::string("borrowed")))) {
      ::setValue(account, std::string("debt"),
                 this->safeString(entry, std::string("borrowed")));
    }
    return account;
  }

  /**
   * @method
   * @name gate#fetchBalance
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-unified-account-information
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#list-spot-trading-accounts
   * @see https://www.gate.com/docs/developers/apiv4/en/#margin-account-list
   * @see https://www.gate.com/docs/developers/apiv4/en/#funding-account-list
   * @see https://www.gate.com/docs/developers/apiv4/en/#get-futures-account
   * @see https://www.gate.com/docs/developers/apiv4/en/#get-futures-account-2
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-account-information
   * @param {object} [params] exchange specific parameters
   * @param {string} [params.type] spot, margin, swap or future, if not provided
   * ::getValue(this, std::string("options"))['defaultType'] is used
   * @param {string} [params.settle] 'btc' or 'usdt' - settle currency for
   * perpetual swap and future - default="usdt" for swap and "btc" for future
   * @param {string} [params.marginMode] 'cross' or 'isolated' - marginMode for
   * margin trading if not provided ::getValue(this,
   * std::string("options"))['defaultMarginMode'] is used
   * @param {string} [params.symbol] margin only - unified ccxt symbol
   * @param {boolean} [params.unifiedAccount] default false, set to true for
   * fetching the unified account balance
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 awaitValue(this->loadUnifiedStatus());
                 ccxt::any symbol =
                     this->safeString(params, std::string("symbol"));
                 params = this->omit(params, std::string("symbol"));
                 ccxt::any isUnifiedAccount = false;
                 ccxt::any isUnifiedAccountparamsVariable =
                     this->handleOptionAndParams(params,
                                                 std::string("fetchBalance"),
                                                 std::string("unifiedAccount"));
                 isUnifiedAccount =
                     ::getValue(isUnifiedAccountparamsVariable, 0);
                 params = ::getValue(isUnifiedAccountparamsVariable, 1);
                 ccxt::any typequeryVariable = this->handleMarketTypeAndParams(
                     std::string("fetchBalance"), ccxt::any{}, params);
                 ccxt::any type = ::getValue(typequeryVariable, 0);
                 ccxt::any query = ::getValue(typequeryVariable, 1);
                 ccxt::any requestrequestParamsVariable =
                     this->prepareRequest(ccxt::any{}, type, query);
                 ccxt::any request =
                     ::getValue(requestrequestParamsVariable, 0);
                 ccxt::any requestParams =
                     ::getValue(requestrequestParamsVariable, 1);
                 ccxt::any marginModerequestQueryVariable =
                     this->getMarginMode(false, requestParams);
                 ccxt::any marginMode =
                     ::getValue(marginModerequestQueryVariable, 0);
                 ccxt::any requestQuery =
                     ::getValue(marginModerequestQueryVariable, 1);
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   ccxt::any market = this->market(symbol);
                   ::setValue(request, std::string("currency_pair"),
                              ::getValue(market, std::string("id")));
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isUnifiedAccount)) {
                   response = awaitValue(this->privateUnifiedGetAccounts(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(type, std::string("spot")))) {
                   if (isTrue(isEqual(marginMode, std::string("spot")))) {
                     response = awaitValue(this->privateSpotGetAccounts(
                         this->extend(request, requestQuery)));
                   } else if (isTrue(
                                  isEqual(marginMode, std::string("margin")))) {
                     response = awaitValue(this->privateMarginGetAccounts(
                         this->extend(request, requestQuery)));
                   } else if (isTrue(isEqual(marginMode,
                                             std::string("cross_margin")))) {
                     response = awaitValue(this->privateMarginGetCrossAccounts(
                         this->extend(request, requestQuery)));
                   } else {
                     throw NotSupported(toString(add(
                         this->id,
                         std::string(
                             " fetchBalance() not support this marginMode"))));
                   }
                 } else if (isTrue(isEqual(type, std::string("funding")))) {
                   response = awaitValue(this->privateMarginGetFundingAccounts(
                       this->extend(request, requestQuery)));
                 } else if (isTrue(isEqual(type, std::string("swap")))) {
                   response = awaitValue(this->privateFuturesGetSettleAccounts(
                       this->extend(request, requestQuery)));
                 } else if (isTrue(isEqual(type, std::string("future")))) {
                   response = awaitValue(this->privateDeliveryGetSettleAccounts(
                       this->extend(request, requestQuery)));
                 } else if (isTrue(isEqual(type, std::string("option")))) {
                   response = awaitValue(this->privateOptionsGetAccounts(
                       this->extend(request, requestQuery)));
                 } else {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(
                           " fetchBalance() not support this market type"))));
                 }
                 ccxt::any contract =
                     (isTrue(isTrue((isEqual(type, std::string("swap")))) ||
                             isTrue((isEqual(type, std::string("future"))))) ||
                      isTrue((isEqual(type, std::string("option")))));
                 if (isTrue(contract)) {
                   response = ccxt::list{response};
                 }
                 //
                 // Spot / margin funding
                 //
                 //     [
                 //         {
                 //             "currency": "DBC",
                 //             "available": "0",
                 //             "locked": "0"
                 //             "lent": "0", // margin funding only
                 //             "total_lent": "0" // margin funding only
                 //         },
                 //         ...
                 //     ]
                 //
                 //  Margin
                 //
                 //    [
                 //        {
                 //            "currency_pair": "DOGE_USDT",
                 //            "locked": false,
                 //            "risk": "9999.99",
                 //            "base": {
                 //                "currency": "DOGE",
                 //                "available": "0",
                 //                "locked": "0",
                 //                "borrowed": "0",
                 //                "interest": "0"
                 //            },
                 //            "quote": {
                 //                "currency": "USDT",
                 //                "available": "0.73402",
                 //                "locked": "0",
                 //                "borrowed": "0",
                 //                "interest": "0"
                 //            }
                 //        },
                 //        ...
                 //    ]
                 //
                 // Cross margin
                 //
                 //    {
                 //        "user_id": 10406147,
                 //        "locked": false,
                 //        "balances": {
                 //            "USDT": {
                 //                "available": "1",
                 //                "freeze": "0",
                 //                "borrowed": "0",
                 //                "interest": "0"
                 //            }
                 //        },
                 //        "total": "1",
                 //        "borrowed": "0",
                 //        "interest": "0",
                 //        "risk": "9999.99"
                 //    }
                 //
                 //  Perpetual Swap
                 //
                 //    {
                 //        "order_margin": "0",
                 //        "point": "0",
                 //        "bonus": "0",
                 //        "history": {
                 //            "dnw": "2.1321",
                 //            "pnl": "11.5351",
                 //            "refr": "0",
                 //            "point_fee": "0",
                 //            "fund": "-0.32340576684",
                 //            "bonus_dnw": "0",
                 //            "point_refr": "0",
                 //            "bonus_offset": "0",
                 //            "fee": "-0.20132775",
                 //            "point_dnw": "0",
                 //        },
                 //        "unrealised_pnl": "13.315100000006",
                 //        "total": "12.51345151332",
                 //        "available": "0",
                 //        "in_dual_mode": false,
                 //        "currency": "USDT",
                 //        "position_margin": "12.51345151332",
                 //        "user": "6333333",
                 //    }
                 //
                 // Delivery Future
                 //
                 //    {
                 //        "order_margin": "0",
                 //        "point": "0",
                 //        "history": {
                 //            "dnw": "1",
                 //            "pnl": "0",
                 //            "refr": "0",
                 //            "point_fee": "0",
                 //            "point_dnw": "0",
                 //            "settle": "0",
                 //            "settle_fee": "0",
                 //            "point_refr": "0",
                 //            "fee": "0",
                 //        },
                 //        "unrealised_pnl": "0",
                 //        "total": "1",
                 //        "available": "1",
                 //        "currency": "USDT",
                 //        "position_margin": "0",
                 //        "user": "6333333",
                 //    }
                 //
                 // option
                 //
                 //     {
                 //         "order_margin": "0",
                 //         "bid_order_margin": "0",
                 //         "init_margin": "0",
                 //         "history": {
                 //             "dnw": "32",
                 //             "set": "0",
                 //             "point_fee": "0",
                 //             "point_dnw": "0",
                 //             "prem": "0",
                 //             "point_refr": "0",
                 //             "insur": "0",
                 //             "fee": "0",
                 //             "refr": "0"
                 //         },
                 //         "total": "32",
                 //         "available": "32",
                 //         "liq_triggered": false,
                 //         "maint_margin": "0",
                 //         "ask_order_margin": "0",
                 //         "point": "0",
                 //         "position_notional_limit": "2000000",
                 //         "unrealised_pnl": "0",
                 //         "equity": "32",
                 //         "user": 5691076,
                 //         "currency": "USDT",
                 //         "short_enabled": false,
                 //         "orders_limit": 10
                 //     }
                 //
                 // unified
                 //
                 //     {
                 //         "user_id": 10001,
                 //         "locked": false,
                 //         "balances": {
                 //             "ETH": {
                 //                 "available": "0",
                 //                 "freeze": "0",
                 //                 "borrowed": "0.075393666654",
                 //                 "negative_liab": "0",
                 //                 "futures_pos_liab": "0",
                 //                 "equity": "1016.1",
                 //                 "total_freeze": "0",
                 //                 "total_liab": "0"
                 //             },
                 //             "POINT": {
                 //                 "available": "9999999999.017023138734",
                 //                 "freeze": "0",
                 //                 "borrowed": "0",
                 //                 "negative_liab": "0",
                 //                 "futures_pos_liab": "0",
                 //                 "equity": "12016.1",
                 //                 "total_freeze": "0",
                 //                 "total_liab": "0"
                 //             },
                 //             "USDT": {
                 //                 "available": "0.00000062023",
                 //                 "freeze": "0",
                 //                 "borrowed": "0",
                 //                 "negative_liab": "0",
                 //                 "futures_pos_liab": "0",
                 //                 "equity": "16.1",
                 //                 "total_freeze": "0",
                 //                 "total_liab": "0"
                 //             }
                 //         },
                 //         "total": "230.94621713",
                 //         "borrowed": "161.66395521",
                 //         "total_initial_margin": "1025.0524665088",
                 //         "total_margin_balance": "3382495.944473949183",
                 //         "total_maintenance_margin": "205.01049330176",
                 //         "total_initial_margin_rate": "3299.827135672679",
                 //         "total_maintenance_margin_rate":
                 //         "16499.135678363399", "total_available_margin":
                 //         "3381470.892007440383", "unified_account_total":
                 //         "3381470.892007440383",
                 //         "unified_account_total_liab": "0",
                 //         "unified_account_total_equity": "100016.1",
                 //         "leverage": "2"
                 //     }
                 //
                 ccxt::any result = ccxt::dict{
                     {std::string("info"), response},
                 };
                 ccxt::any isolated =
                     isTrue(isEqual(marginMode, std::string("margin"))) &&
                     isTrue(isEqual(type, std::string("spot")));
                 ccxt::any data = response;
                 if (isTrue(inOp(data, std::string("balances")))) {
                   ccxt::any flatBalances = ccxt::list{};
                   ccxt::any balances = this->safeValue(
                       data, std::string("balances"), ccxt::list{});
                   // inject currency and create an artificial balance object
                   // so it can follow the existent flow
                   ccxt::any keys = getObjectKeys(balances);
                   for (ccxt::any i = 0; isLessThan(i, getArrayLength(keys));
                        postFixIncrement(i)) {
                     ccxt::any currencyId = ::getValue(keys, i);
                     ccxt::any content = ::getValue(balances, currencyId);
                     ::setValue(content, std::string("currency"), currencyId);
                     arrayPush(flatBalances, content);
                   }
                   data = flatBalances;
                 }
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(data));
                      postFixIncrement(i)) {
                   ccxt::any entry = ::getValue(data, i);
                   if (isTrue(isolated)) {
                     ccxt::any marketId =
                         this->safeString(entry, std::string("currency_pair"));
                     ccxt::any symbolInner = this->safeSymbol(
                         marketId, ccxt::any{}, std::string("_"),
                         std::string("margin"));
                     ccxt::any base = this->safeValue(
                         entry, std::string("base"), ccxt::dict{});
                     ccxt::any quote = this->safeValue(
                         entry, std::string("quote"), ccxt::dict{});
                     ccxt::any baseCode = this->safeCurrencyCode(
                         this->safeString(base, std::string("currency")));
                     ccxt::any quoteCode = this->safeCurrencyCode(
                         this->safeString(quote, std::string("currency")));
                     ccxt::any subResult = ccxt::dict{};
                     ::setValue(subResult, baseCode,
                                this->parseBalanceHelper(base));
                     ::setValue(subResult, quoteCode,
                                this->parseBalanceHelper(quote));
                     ::setValue(result, symbolInner,
                                this->safeBalance(subResult));
                   } else {
                     ccxt::any code = this->safeCurrencyCode(
                         this->safeString(entry, std::string("currency")));
                     ::setValue(result, code, this->parseBalanceHelper(entry));
                   }
                 }
                 ccxt::any returnResult =
                     (isTrue(isolated) ? ccxt::any(result)
                                       : ccxt::any(this->safeBalance(result)));
                 return returnResult;
               })
        .share();
  }

  /**
   * @method
   * @name gate#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://www.gate.com/docs/developers/apiv4/en/#market-k-line-chart //
   * spot
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#futures-market-k-line-chart
   * // swap
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#futures-market-k-line-chart-2
   * // future
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#options-contract-market-candlestick-chart
   * // option
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch, limit is
   * conflicted with since and params["until"], If either since and
   * params["until"] is specified, request will be rejected
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.price] "mark" or "index" for mark price and index
   * price candles
   * @param {int} [params.until] timestamp in ms of the latest candle to fetch
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume (units in quote currency)
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, 1000));
                 }
                 if (isTrue(isEqual(::getValue(market, std::string("option")),
                                    true))) {
                   return awaitValue(this->fetchOptionOHLCV(
                       symbol, timeframe, since, limit, params));
                 }
                 ccxt::any price =
                     this->safeString(params, std::string("price"));
                 ccxt::any request = ccxt::dict{};
                 ccxt::any requestparamsVariable =
                     this->prepareRequest(market, ccxt::any{}, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ::setValue(
                     request, std::string("interval"),
                     this->safeString(this->timeframes, timeframe, timeframe));
                 ccxt::any maxLimit =
                     (isTrue((isEqual(
                          ::getValue(market, std::string("contract")), true)))
                          ? ccxt::any(1999)
                          : ccxt::any(1000));
                 limit = (isTrue((isEqual(limit, ccxt::any{})))
                              ? ccxt::any(maxLimit)
                              : ccxt::any(mathMin(limit, maxLimit)));
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   until = this->parseToInt(divide(until, 1000));
                   params = this->omit(params, std::string("until"));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ccxt::any duration = this->parseTimeframe(timeframe);
                   ::setValue(request, std::string("from"),
                              this->parseToInt(divide(since, 1000)));
                   ccxt::any distance =
                       multiply((subtract(limit, 1)), duration);
                   ccxt::any toTimestamp = this->sum(
                       ::getValue(request, std::string("from")), distance);
                   ccxt::any currentTimestamp = this->seconds();
                   ccxt::any to = mathMin(toTimestamp, currentTimestamp);
                   if (isTrue(!isEqual(until, ccxt::any{}))) {
                     ::setValue(request, std::string("to"), mathMin(to, until));
                   } else {
                     ::setValue(request, std::string("to"), to);
                   }
                 } else {
                   if (isTrue(!isEqual(until, ccxt::any{}))) {
                     ::setValue(request, std::string("to"), until);
                   }
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = ccxt::list{};
                 if (isTrue(isEqual(::getValue(market, std::string("contract")),
                                    true))) {
                   ccxt::any isMark = (isEqual(price, std::string("mark")));
                   ccxt::any isIndex = (isEqual(price, std::string("index")));
                   if (isTrue(isTrue(isMark) || isTrue(isIndex))) {
                     ::setValue(request, std::string("contract"),
                                add(add(price, std::string("_")),
                                    ::getValue(market, std::string("id"))));
                     params = this->omit(params, std::string("price"));
                   }
                   if (isTrue(isEqual(::getValue(market, std::string("future")),
                                      true))) {
                     response =
                         awaitValue(this->publicDeliveryGetSettleCandlesticks(
                             this->extend(request, params)));
                   } else if (isTrue(isEqual(
                                  ::getValue(market, std::string("swap")),
                                  true))) {
                     response =
                         awaitValue(this->publicFuturesGetSettleCandlesticks(
                             this->extend(request, params)));
                   }
                 } else {
                   response = awaitValue(this->publicSpotGetCandlesticks(
                       this->extend(request, params)));
                 }
                 return this->parseOHLCVs(this->toArray(response), market,
                                          timeframe, since, limit);
               })
        .share();
  }

  virtual std::shared_future<ccxt::any>
  fetchOptionOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
                   ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
                   ccxt::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        // separated option logic because the from, to and limit
                        // parameters weren't functioning
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{};
                        ccxt::any requestparamsVariable =
                            this->prepareRequest(market, ccxt::any{}, params);
                        request = ::getValue(requestparamsVariable, 0);
                        params = ::getValue(requestparamsVariable, 1);
                        ::setValue(request, std::string("interval"),
                                   this->safeString(this->timeframes, timeframe,
                                                    timeframe));
                        ccxt::any response =
                            awaitValue(this->publicOptionsGetCandlesticks(
                                this->extend(request, params)));
                        return this->parseOHLCVs(this->toArray(response),
                                                 market, timeframe, since,
                                                 limit);
                      })
        .share();
  }

  /**
   * @method
   * @name gate#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#get-all-futures-trading-statistics
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
   * @param {int} [limit] the maximum amount of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest funding rate to
   * fetch
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingRateHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingRateHistory"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchFundingRateHistory"), symbol, since,
                       limit, std::string("8h"), params));
                 }
                 ccxt::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("swap")),
                                     true))) {
                   throw BadSymbol(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "supports swap contracts only"))));
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any requestparamsVariable =
                     this->prepareRequest(market, ccxt::any{}, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("from"),
                              this->parseToInt(divide(since, 1000)));
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params = this->omit(params, std::string("until"));
                   ::setValue(request, std::string("to"),
                              this->parseToInt(divide(until, 1000)));
                 }
                 ccxt::any response =
                     awaitValue(this->publicFuturesGetSettleFundingRate(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "r": "0.00063521",
                 //         "t": "1621267200000",
                 //     }
                 //
                 ccxt::any rates = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(response));
                      postFixIncrement(i)) {
                   ccxt::any entry = this->safeDict(response, i, ccxt::dict{});
                   ccxt::any timestamp =
                       this->safeTimestamp(entry, std::string("t"));
                   arrayPush(
                       rates,
                       ccxt::dict{
                           {std::string("info"), entry},
                           {std::string("symbol"), symbol},
                           {std::string("fundingRate"),
                            this->safeNumber(entry, std::string("r"))},
                           {std::string("timestamp"), timestamp},
                           {std::string("datetime"), this->iso8601(timestamp)},
                       });
                 }
                 ccxt::any sorted =
                     this->sortBy(rates, std::string("timestamp"));
                 return this->filterBySymbolSinceLimit(
                     sorted, ::getValue(market, std::string("symbol")), since,
                     limit);
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    // Spot market candles
    //
    //    [
    //        "1660957920", // timestamp
    //        "6227.070147198573", // quote volume
    //        "0.0000133485", // close
    //        "0.0000133615", // high
    //        "0.0000133347", // low
    //        "0.0000133468", // open
    //        "466641934.99" // base volume
    //    ]
    //
    //
    // Swap, Future, Option, Mark and Index price candles
    //
    //     {
    //          "t":1632873600,         // Unix timestamp in seconds
    //          "o": "41025",           // Open price
    //          "h": "41882.17",        // Highest price
    //          "c": "41776.92",        // Close price
    //          "l": "40783.94"         // Lowest price
    //     }
    //
    if (isTrue(isArray(ohlcv))) {
      return ccxt::list{
          this->safeTimestamp(ohlcv, 0), this->safeNumber(ohlcv, 5),
          this->safeNumber(ohlcv, 3),    this->safeNumber(ohlcv, 4),
          this->safeNumber(ohlcv, 2),    this->safeNumber(ohlcv, 6)};
    } else {
      // Swap, Future, Option, Mark and Index price candles
      return ccxt::list{this->safeTimestamp(ohlcv, std::string("t")),
                        this->safeNumber(ohlcv, std::string("o")),
                        this->safeNumber(ohlcv, std::string("h")),
                        this->safeNumber(ohlcv, std::string("l")),
                        this->safeNumber(ohlcv, std::string("c")),
                        this->safeNumber(ohlcv, std::string("v"))};
    }
  }

  /**
   * @method
   * @name gate#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-market-transaction-records
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#futures-market-transaction-records
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#futures-market-transaction-records-2
   * @see https://www.gate.com/docs/developers/apiv4/en/#market-trade-records
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest trade to fetch
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchTrades"), symbol, since, limit,
                       params));
                 }
                 ccxt::any market = this->market(symbol);
                 //
                 // spot
                 //
                 //     const request: Dict = {
                 //         'currency_pair': market['id'],
                 //         'limit': limit, // maximum number of records to be
                 //         returned in a single list 'last_id': 'id', //
                 //         specify list staring point using the id of last
                 //         record in previous list-query results 'reverse':
                 //         false, // true to retrieve records where id is
                 //         smaller than the specified last_id, false to
                 //         retrieve records where id is larger than the
                 //         specified last_id
                 //     };
                 //
                 // swap, future
                 //
                 //     const request: Dict = {
                 //         'settle': market['settleId'],
                 //         'contract': market['id'],
                 //         'limit': limit, // maximum number of records to be
                 //         returned in a single list 'last_id': 'id', //
                 //         specify list staring point using the id of last
                 //         record in previous list-query results 'from': since
                 //         / 1000), // starting time in seconds, if not
                 //         specified, to and limit will be used to limit
                 //         response items 'to': this.seconds (), // end time in
                 //         seconds, default to current time
                 //     };
                 //
                 ccxt::any requestqueryVariable =
                     this->prepareRequest(market, ccxt::any{}, params);
                 ccxt::any request = ::getValue(requestqueryVariable, 0);
                 ccxt::any query = ::getValue(requestqueryVariable, 1);
                 ccxt::any until = this->safeInteger2(params, std::string("to"),
                                                      std::string("until"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params =
                       this->omit(params, ccxt::list{std::string("until")});
                   ::setValue(request, std::string("to"),
                              this->parseToInt(divide(until, 1000)));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1000)); // default 100, max 1000
                 }
                 if (isTrue(isTrue(!isEqual(since, ccxt::any{})) &&
                            isTrue((isEqual(
                                ::getValue(market, std::string("contract")),
                                true))))) {
                   ::setValue(request, std::string("from"),
                              this->parseToInt(divide(since, 1000)));
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(
                         isTrue(isEqual(::getValue(market, std::string("type")),
                                        std::string("spot"))) ||
                         isTrue(isEqual(::getValue(market, std::string("type")),
                                        std::string("margin"))))) {
                   response = awaitValue(
                       this->publicSpotGetTrades(this->extend(request, query)));
                 } else if (isTrue(
                                isEqual(::getValue(market, std::string("swap")),
                                        true))) {
                   response = awaitValue(this->publicFuturesGetSettleTrades(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(
                                ::getValue(market, std::string("future")),
                                true))) {
                   response = awaitValue(this->publicDeliveryGetSettleTrades(
                       this->extend(request, query)));
                 } else if (isTrue(
                                isEqual(::getValue(market, std::string("type")),
                                        std::string("option")))) {
                   response = awaitValue(this->publicOptionsGetTrades(
                       this->extend(request, query)));
                 } else {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(
                           " fetchTrades() not support this market type."))));
                 }
                 //
                 // spot
                 //
                 //     [
                 //         {
                 //             "id": "1852958144",
                 //             "create_time": "1634673259",
                 //             "create_time_ms": "1634673259378.105000",
                 //             "currency_pair": "ADA_USDT",
                 //             "side": "sell",
                 //             "amount": "307.078",
                 //             "price": "2.104",
                 //         }
                 //     ]
                 //
                 // perpetual swap
                 //
                 //     [
                 //         {
                 //              "size": "2",
                 //              "id": "2522911",
                 //              "create_time_ms": "1634673380.182",
                 //              "create_time": "1634673380.182",
                 //              "contract": "ADA_USDT",
                 //              "price": "2.10486",
                 //         }
                 //     ]
                 //
                 // option
                 //
                 //     [
                 //         {
                 //             "size": -5,
                 //             "id": 25,
                 //             "create_time": 1682378573,
                 //             "contract": "ETH_USDT-20230526-2000-P",
                 //             "price": "209.1"
                 //         }
                 //     ]
                 //
                 return this->parseTrades(response, market, since, limit);
               })
        .share();
  }

