  /**
   * @method
   * @name gate#fetchMyTrades
   * @description Fetch personal trading history
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-personal-trading-records
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-personal-trading-records-by-time-range
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-personal-trading-records-3
   * @see
   * https://www.gate.com/docs/developers/apiv4/en/#query-personal-trading-records-4
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] 'cross' or 'isolated' - marginMode for
   * margin trading if not provided ::getValue(this,
   * std::string("options"))['defaultMarginMode'] is used
   * @param {string} [params.type] 'spot', 'swap', or 'future', if not provided
   * ::getValue(this, std::string("options"))['defaultMarginMode'] is used
   * @param {int} [params.until] The latest timestamp, in ms, that fetched
   * trades were made
   * @param {int} [params.page] *spot only* Page number
   * @param {string} [params.order_id] *spot only* Filter trades with specified
   * order ID. symbol is also required if this field is present
   * @param {string} [params.order] *contract only* Futures order ID, return
   * related data only if specified
   * @param {int} [params.offset] *contract only* list offset, starting from 0
   * @param {string} [params.last_id] *contract only* specify list staring point
   * using the id of last record in previous list-query results
   * @param {int} [params.count_total] *contract only* whether to return total
   * number matched, default to 0(no return)
   * @param {bool} [params.unifiedAccount] set to true for fetching trades in a
   * unified account
   * @param {bool} [params.paginate] default false, when true will automatically
   * paginate by calling this endpoint multiple times. See in the docs all the
   * [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 awaitValue(this->loadUnifiedStatus());
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMyTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params));
                 }
                 ccxt::any type = ccxt::any{};
                 ccxt::any marginMode = ccxt::any{};
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = (isTrue((!isEqual(symbol, ccxt::any{})))
                                         ? ccxt::any(this->market(symbol))
                                         : ccxt::any(ccxt::any{}));
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 params = this->omit(params, ccxt::list{std::string("until")});
                 ccxt::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchMyTrades"), market, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 ccxt::any contract =
                     isTrue(isTrue((isEqual(type, std::string("swap")))) ||
                            isTrue((isEqual(type, std::string("future"))))) ||
                     isTrue((isEqual(type, std::string("option"))));
                 if (isTrue(contract)) {
                   ccxt::any requestparamsVariable =
                       this->prepareRequest(market, type, params);
                   request = ::getValue(requestparamsVariable, 0);
                   params = ::getValue(requestparamsVariable, 1);
                   if (isTrue(isEqual(type, std::string("option")))) {
                     params = this->omit(params, std::string("order_id"));
                   }
                 } else {
                   if (isTrue(!isEqual(market, ccxt::any{}))) {
                     ::setValue(
                         request, std::string("currency_pair"),
                         ::getValue(market,
                                    std::string("id"))); // Should always be set
                                                         // for non-trigger
                   }
                   ccxt::any marginModeparamsVariable =
                       this->getMarginMode(false, params);
                   marginMode = ::getValue(marginModeparamsVariable, 0);
                   params = ::getValue(marginModeparamsVariable, 1);
                   ::setValue(request, std::string("account"), marginMode);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // default 100, max 1000
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("from"),
                              this->parseToInt(divide(since, 1000)));
                 }
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   ::setValue(request, std::string("to"),
                              this->parseToInt(divide(until, 1000)));
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isTrue(isEqual(type, std::string("spot"))) ||
                            isTrue(isEqual(type, std::string("margin"))))) {
                   response = awaitValue(this->privateSpotGetMyTrades(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(type, std::string("swap")))) {
                   response = awaitValue(
                       this->privateFuturesGetSettleMyTradesTimerange(
                           this->extend(request, params)));
                 } else if (isTrue(isEqual(type, std::string("future")))) {
                   response = awaitValue(this->privateDeliveryGetSettleMyTrades(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(type, std::string("option")))) {
                   response = awaitValue(this->privateOptionsGetMyTrades(
                       this->extend(request, params)));
                 } else {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(
                           " fetchMyTrades() not support this market type."))));
                 }
                 //
                 // spot
                 //
                 //     [
                 //         {
                 //             "id": "2876130500",
                 //             "create_time": "1645464610",
                 //             "create_time_ms": "1645464610777.399200",
                 //             "currency_pair": "DOGE_USDT",
                 //             "side": "sell",
                 //             "role": "taker",
                 //             "amount": "10.97",
                 //             "price": "0.137384",
                 //             "order_id": "125924049993",
                 //             "fee": "0.00301420496",
                 //             "fee_currency": "USDT",
                 //             "point_fee": "0",
                 //             "gt_fee": "0"
                 //         }
                 //     ]
                 //
                 // perpetual swap
                 //
                 //     [
                 //         {
                 //             "size": -5,
                 //             "order_id": "130264979823",
                 //             "id": 26884791,
                 //             "role": "taker",
                 //             "create_time": 1645465199.5472,
                 //             "contract": "DOGE_USDT",
                 //             "price": "0.136888"
                 //         }
                 //     ]
                 //
                 // future
                 //
                 //     [
                 //         {
                 //             "id": 121234231,
                 //             "create_time": 1514764800.123,
                 //             "contract": "BTC_USDT",
                 //             "order_id": "21893289839",
                 //             "size": 100,
                 //             "price": "100.123",
                 //             "role": "taker"
                 //         }
                 //     ]
                 //
                 // option
                 //
                 //     [
                 //         {
                 //             "underlying_price": "26817.84",
                 //             "size": -1,
                 //             "contract": "BTC_USDT-20230602-26500-C",
                 //             "id": 16,
                 //             "role": "taker",
                 //             "create_time": 1685594770,
                 //             "order_id": 2611026125,
                 //             "price": "333"
                 //         }
                 //     ]
                 //
                 return this->parseTrades(response, market, since, limit);
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // public
    //
    //  spot:
    //     {
    //         "id": "1334253759",
    //         "create_time": "1626342738",
    //         "create_time_ms": "1626342738331.497000",
    //         "currency_pair": "BTC_USDT",
    //         "side": "sell",
    //         "amount": "0.0022",
    //         "price": "32452.16"
    //     }
    //
    //  swap:
    //
    //    {
    //        "id": "442288327",
    //        "contract": "BTC_USDT",
    //        "create_time": "1739814676.707",
    //        "create_time_ms": "1739814676.707",
    //        "size": "-105",
    //        "price": "95594.8"
    //    }
    //
    //
    // public ws
    //
    //     {
    //         "id": 221994511,
    //         "time": 1580311438.618647,
    //         "price": "9309",
    //         "amount": "0.0019",
    //         "type": "sell"
    //     }
    //
    // spot rest
    //
    //     {
    //         "id": "2876130500",
    //         "create_time": "1645464610",
    //         "create_time_ms": "1645464610777.399200",
    //         "currency_pair": "DOGE_USDT",
    //         "side": "sell",
    //         "role": "taker",
    //         "amount": "10.97",
    //         "price": "0.137384",
    //         "order_id": "125924049993",
    //         "fee": "0.00301420496",
    //         "fee_currency": "USDT",
    //         "point_fee": "1.1",
    //         "gt_fee":"2.2"
    //     }
    //
    // perpetual swap rest
    //
    //     {
    //         "size": -5,
    //         "order_id": "130264979823",
    //         "id": 26884791,
    //         "role": "taker",
    //         "create_time": 1645465199.5472,
    //         "contract": "DOGE_USDT",
    //         "price": "0.136888"
    //     }
    //
    // future rest
    //
    //     {
    //         "id": 121234231,
    //         "create_time": 1514764800.123,
    //         "contract": "BTC_USDT",
    //         "order_id": "21893289839",
    //         "size": 100,
    //         "price": "100.123",
    //         "role": "taker"
    //     }
    //
    // fetchTrades: option
    //
    //     {
    //         "size": -5,
    //         "id": 25,
    //         "create_time": 1682378573,
    //         "contract": "ETH_USDT-20230526-2000-P",
    //         "price": "209.1"
    //     }
    //
    // fetchMyTrades: option
    //
    //     {
    //         "underlying_price": "26817.84",
    //         "size": -1,
    //         "contract": "BTC_USDT-20230602-26500-C",
    //         "id": 16,
    //         "role": "taker",
    //         "create_time": 1685594770,
    //         "order_id": 2611026125,
    //         "price": "333"
    //     }
    //
    ccxt::any id =
        this->safeString2(trade, std::string("id"), std::string("trade_id"));
    ccxt::any timestamp = ccxt::any{};
    ccxt::any msString = this->safeString(trade, std::string("create_time_ms"));
    if (isTrue(!isEqual(msString, ccxt::any{}))) {
      msString = ccxt::Precise::stringMul(msString, std::string("1000"));
      msString = slice(msString, 0, 13);
      timestamp = this->parseToInt(msString);
    } else {
      timestamp = this->safeTimestamp2(trade, std::string("time"),
                                       std::string("create_time"));
    }
    ccxt::any marketId = this->safeString2(trade, std::string("currency_pair"),
                                           std::string("contract"));
    ccxt::any marketType = (isTrue((inOp(trade, std::string("contract"))))
                                ? ccxt::any(std::string("contract"))
                                : ccxt::any(std::string("spot")));
    market = this->safeMarket(marketId, market, std::string("_"), marketType);
    ccxt::any amountString =
        this->safeString2(trade, std::string("amount"), std::string("size"));
    ccxt::any priceString = this->safeString(trade, std::string("price"));
    ccxt::any contractSide =
        (isTrue(ccxt::Precise::stringLt(amountString, std::string("0")))
             ? ccxt::any(std::string("sell"))
             : ccxt::any(std::string("buy")));
    amountString = ccxt::Precise::stringAbs(amountString);
    ccxt::any side = this->safeString2(trade, std::string("side"),
                                       std::string("type"), contractSide);
    ccxt::any orderId = this->safeString(trade, std::string("order_id"));
    ccxt::any feeAmount = this->safeString(trade, std::string("fee"));
    ccxt::any gtFee =
        this->omitZero(this->safeString(trade, std::string("gt_fee")));
    ccxt::any pointFee =
        this->omitZero(this->safeString(trade, std::string("point_fee")));
    ccxt::any fees = ccxt::list{};
    if (isTrue(!isEqual(feeAmount, ccxt::any{}))) {
      ccxt::any feeCurrencyId =
          this->safeString(trade, std::string("fee_currency"));
      ccxt::any feeCurrencyCode = this->safeCurrencyCode(feeCurrencyId);
      if (isTrue(isEqual(feeCurrencyCode, ccxt::any{}))) {
        feeCurrencyCode = this->safeString(market, std::string("settle"));
      }
      arrayPush(fees, ccxt::dict{
                          {std::string("cost"), feeAmount},
                          {std::string("currency"), feeCurrencyCode},
                      });
    }
    if (isTrue(!isEqual(gtFee, ccxt::any{}))) {
      arrayPush(fees, ccxt::dict{
                          {std::string("cost"), gtFee},
                          {std::string("currency"), std::string("GT")},
                      });
    }
    if (isTrue(!isEqual(pointFee, ccxt::any{}))) {
      arrayPush(fees, ccxt::dict{
                          {std::string("cost"), pointFee},
                          {std::string("currency"), std::string("GATEPOINT")},
                      });
    }
    ccxt::any takerOrMaker = this->safeString(trade, std::string("role"));
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("id"), id},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("order"), orderId},
            {std::string("type"), ccxt::any{}},
            {std::string("side"), side},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), ccxt::any{}},
            {std::string("fees"), fees},
        },
        market);
  }

  /**
   * @method
   * @name gate#fetchDeposits
   * @description fetch all deposits made to an account
   * @see https://www.gate.com/docs/developers/apiv4/en/#get-deposit-records
   * @param {string} code unified currency code
   * @param {int} [since] the earliest time in ms to fetch deposits for
   * @param {int} [limit] the maximum number of deposits structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] end time in ms
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  fetchDeposits(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchDeposits"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchDeposits"), code, since, limit,
                       params));
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any currency = ccxt::any{};
                 if (isTrue(!isEqual(code, ccxt::any{}))) {
                   currency = this->currency(code);
                   ::setValue(
                       request, std::string("currency"),
                       ::getValue(currency,
                                  std::string("id"))); // todo: currencies have
                                                       // network-junctions
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ccxt::any start = this->parseToInt(divide(since, 1000));
                   ::setValue(request, std::string("from"), start);
                   ::setValue(
                       request, std::string("to"),
                       this->sum(start,
                                 multiply(multiply(multiply(30, 24), 60), 60)));
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("to"), request, params, 0.001);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response = awaitValue(this->privateWalletGetDeposits(
                     this->extend(request, params)));
                 return this->parseTransactions(response, currency);
               })
        .share();
  }

