                //            "fill_price": "0",
                //            "user": 6693577,
                //            "finish_as": "cancelled",
                //            "status": "finished",
                //            "is_liq": false,
                //            "refu": 2436035,
                //            "is_close": false,
                //            "iceberg": 0
                //        }
